# Chunking strategies (conceptual)
def fixed_chunks(text, size=500):
    return [text[i:i+size] for i in range(0, len(text), size)]

def sentence_chunks(text):
    sentences = text.split(". ")
    chunks = []
    current = ""
    for s in sentences:
        if len(current) + len(s) < 500:
            current += s + ". "
        else:
            chunks.append(current.strip())
            current = s + ". "
    if current:
        chunks.append(current.strip())
    return chunks

text = "First sentence. Second sentence. Third sentence. " * 20
print(f"Fixed: {len(fixed_chunks(text))} chunks")
print(f"Sentences: {len(sentence_chunks(text))} chunks")

# Retrieval evaluation metrics
def recall_at_k(retrieved, relevant, k):
    top_k = set(retrieved[:k])
    return len(top_k & set(relevant)) / len(relevant)

def mrr(retrieved, relevant):
    for rank, doc in enumerate(retrieved, 1):
        if doc in relevant:
            return 1 / rank
    return 0

retrieved = ["d3", "d1", "d4", "d2", "d5"]
relevant = ["d1", "d4"]

print(f"Recall@3: {recall_at_k(retrieved, relevant, 3):.2f}")
print(f"MRR:      {mrr(retrieved, relevant):.2f}")
